if(request.method!=='POST')fail('Method not allowed.',405);if(request.headers.get('origin')!==url.origin)fail('Request origin rejected.',403);if(!request.headers.get('content-type')?.includes('application/json'))fail('Expected JSON.',415);const reader=request.body?.getReader();if(!reader)fail('Missing data.');let size=0,parts=[];while(true){const{value,done}=await reader.read();if(done)break;size+=value.length;if(size>260000){await reader.cancel();fail('Upload exceeds the size limit.',413);}parts.push(value);}const bytes=new Uint8Array(size);let pos=0;for(const p of parts){bytes.set(p,pos);pos+=p.length;}let input;try{input=JSON.parse(new TextDecoder().decode(bytes));}catch{fail('Invalid JSON.');}if(!input||input.self!==self)fail('Your account changed. Reload before saving.',409);const id=mine?.public_id||crypto.randomUUID();const ensure=async()=>env.DB.prepare('INSERT INTO learner_preferences (user_id,public_id,public_name,location,discoverable,share_location,share_photo,personalize,photo_key,updated_at) VALUES (?,?,\'\',\'\',0,0,0,0,NULL,?) ON CONFLICT(user_id) DO NOTHING').bind(user,id,Date.now()).run();await ensure();
if(input.action==='preferences'){if(!Number.isSafeInteger(input.preferenceRevision))fail('Reload to check current privacy preferences.',409);const p=input.preferences;if(!p||typeof p.publicName!=='string'||p.publicName.trim().length>60||typeof p.location!=='string'||p.location.trim().length>80||['discoverable','shareLocation','sharePhoto','personalize'].some(k=>typeof p[k]!=='boolean')||p.discoverable&&p.publicName.trim().length<2)fail('Use a public name of 2–60 characters when discoverable, and a city or region under 80 characters.');const result=await env.DB.batch([env.DB.prepare('UPDATE learner_preferences SET public_name=?,public_name_search=?,location=?,location_search=?,discoverable=?,share_location=?,share_photo=?,personalize=?,rec_epoch=rec_epoch+1,preference_rev=preference_rev+1,updated_at=? WHERE user_id=? AND preference_rev=? RETURNING user_id').bind(p.publicName.trim(),p.publicName.trim().normalize('NFKC').toLowerCase(),p.location.trim(),p.location.trim().normalize('NFKC').toLowerCase(),+p.discoverable,+p.shareLocation,+p.sharePhoto,+p.personalize,Date.now(),user,input.preferenceRevision),env.DB.prepare('DELETE FROM recommendation_signals WHERE user_id=? AND EXISTS(SELECT 1 FROM learner_preferences WHERE user_id=? AND personalize=0)').bind(user,user)]);if(!result[0]?.results?.length)fail('Privacy preferences changed in another tab. Reload and review them before saving.',409);}else if(input.action==='personalize'){if(typeof input.enabled!=='boolean')fail('Invalid preference.');await env.DB.batch([env.DB.prepare('UPDATE learner_preferences SET personalize=?,rec_epoch=rec_epoch+1,preference_rev=preference_rev+1,updated_at=? WHERE user_id=?').bind(+input.enabled,Date.now(),user),env.DB.prepare('DELETE FROM recommendation_signals WHERE user_id=? AND EXISTS(SELECT 1 FROM learner_preferences WHERE user_id=? AND personalize=0)').bind(user,user)]);}else if(input.action==='clearSignals'){await env.DB.batch([env.DB.prepare('UPDATE learner_preferences SET rec_epoch=rec_epoch+1 WHERE user_id=?').bind(user),env.DB.prepare('DELETE FROM recommendation_signals WHERE user_id=?').bind(user)]);}else if(input.action==='signal'){if(!['view','search'].includes(input.kind)||typeof input.courseId!=='string'||typeof input.query!=='string')fail('Invalid activity.');const valid=['python-dsa','java-basics',...courses.map(c=>c.id)];if(input.kind==='view'&&!valid.includes(input.courseId))fail('Unknown course.');const q=input.query.trim().slice(0,120);if(input.kind==='search'&&(!q||/@|sk-|password|secret|token|\d{8}/i.test(q)))return learnerResponse({ok:true,recorded:false});await env.DB.batch([env.DB.prepare('INSERT INTO recommendation_signals (id,user_id,kind,course_id,query,created_at) SELECT ?,?,?,?,?,? WHERE EXISTS(SELECT 1 FROM learner_preferences WHERE user_id=? AND personalize=1 AND rec_epoch=?)').bind(crypto.randomUUID(),user,input.kind,input.kind==='view'?input.courseId:'',input.kind==='search'?q:'',Date.now(),user,Number.isSafeInteger(input.epoch)?input.epoch:-1),env.DB.prepare('DELETE FROM recommendation_signals WHERE user_id=? AND id NOT IN(SELECT id FROM recommendation_signals WHERE user_id=? ORDER BY created_at DESC LIMIT 30)').bind(user,user)]);return learnerResponse({ok:true});}else if(input.action==='photo'){if(!Number.isSafeInteger(input.photoRevision)||input.photoRevision!==(mine?.photo_rev||0))fail('The profile photo changed. Reload to review it before retrying.',409);if(typeof input.dataUrl!=='string'||!/^data:image\/(webp|png);base64,/.test(input.dataUrl))fail('Upload a processed WebP or PNG photo.');const[type,b64]=input.dataUrl.split(';base64,');let binary;try{binary=sanitizePhoto(Uint8Array.from(atob(b64),c=>c.charCodeAt(0)),type.slice(5));}catch(e){fail(e.message||'Invalid photo.');}if(!env.FILES?.put)fail('Photo storage is temporarily unavailable.',503);const key='profile-photos/'+user+'/'+crypto.randomUUID()+(type.endsWith('png')?'.png':'.webp');await env.FILES.put(key,binary,{httpMetadata:{contentType:type.slice(5)}});try{const changed=await first('UPDATE learner_preferences SET photo_key=?,photo_rev=photo_rev+1,updated_at=? WHERE user_id=? AND photo_rev=? RETURNING photo_key',key,Date.now(),user,input.photoRevision);if(!changed)fail('The profile photo changed during upload. Reload before retrying.',409);}catch(e){await env.FILES.delete(key).catch(()=>{});throw e;}if(mine?.photo_key)await env.FILES.delete(mine.photo_key).catch(()=>{});}else if(input.action==='removePhoto'){if(!Number.isSafeInteger(input.photoRevision))fail('Reload to check the current photo revision.',409);const removed=await first('UPDATE learner_preferences SET photo_key=NULL,photo_rev=photo_rev+1,updated_at=? WHERE user_id=? AND photo_rev=? RETURNING user_id',Date.now(),user,input.photoRevision);if(!removed)fail('The profile photo changed. Reload before removing it.',409);if(mine?.photo_key)await env.FILES.delete(mine.photo_key).catch(()=>{});}else fail('Unknown learner action.');mine=await first('SELECT * FROM learner_preferences WHERE user_id=?',user);return learnerResponse(own());
